using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Navmesh geometry (NVNM) fields get xEdit's names (wbDefinitionsSF1 wbNavmeshEdgeLinks, wbNavmeshDoorTriangles,
// wbNavmeshWaypoints):
// - An edge link starts with its Type (Portal, Ledge Up, Ledge Down, Enable/Disable Portal; all 163,764 in
//   Starfield.esm are Portal) and ends with the Edge Index (0, 1 or 2).
// - A door triangle's 4 bytes after the triangle are xEdit's CRC Hash (all 948 = 0xE48B73F3, PathingDoor).
// - A waypoint ends with Flags (no bits named; all 37,156 are 0).
// Each test reads a whole navmesh from Starfield.esm with both readers and writes it back byte for byte.
public class NavmeshFieldNameTests
{
    private static IEnumerable<INavigationMeshGetter> Read(string hex)
        => ReadBoth<INavigationMeshGetter>(Record("NAVM", Hex(hex)), f => NavigationMesh.CreateFromBinary(f), (s, p) => NavigationMeshBinaryOverlay.NavigationMeshFactory(s, p));

    private static void WritesBack(INavigationMeshGetter navm, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => navm.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // [no EditorID] (2EF9EF:Starfield.esm)
    private const string Edges = "";
    // [no EditorID] (317EB1:Starfield.esm)
    private const string Door = "";
    // [no EditorID] (12973D:Starfield.esm)
    private const string Waypoints = "";

    [Fact]
    public void EdgeLinks_TypeAndEdgeIndex()
    {
        foreach (var navm in Read(Edges))
        {
            var links = navm.NavmeshGeometry.ShouldNotBeNull().EdgeLinks;
            links.ShouldNotBeEmpty();
            links.ShouldAllBe(l => l.Type == EdgeLink.EdgeLinkType.Portal);
            links.ShouldAllBe(l => l.EdgeIndex >= 0 && l.EdgeIndex <= 2);
            WritesBack(navm, Edges);
        }
    }

    [Fact]
    public void DoorTriangles_CrcHash()
    {
        foreach (var navm in Read(Door))
        {
            var doors = navm.NavmeshGeometry.ShouldNotBeNull().DoorTriangles;
            doors.ShouldNotBeEmpty();
            doors.ShouldAllBe(d => d.CrcHash == 0xE48B73F3);
            WritesBack(navm, Door);
        }
    }

    [Fact]
    public void Waypoints_Flags()
    {
        foreach (var navm in Read(Waypoints))
        {
            var waypoints = navm.NavmeshGeometry.ShouldNotBeNull().Waypoints;
            waypoints.ShouldNotBeEmpty();
            waypoints.ShouldAllBe(w => w.Flags == 0);
            WritesBack(navm, Waypoints);
        }
    }
}
